def boxes(g):
    seen=set(); res=[]
    for i,row in enumerate(g):
        for j,c in enumerate(row):
            if c and (i,j) not in seen:
                # find extent of color c
                cells=[(a,b) for a,r in enumerate(g) for b,x in enumerate(r) if x==c]
                rs=[a for a,_ in cells]; cs=[b for _,b in cells]
                res.append((c,min(rs),max(rs),min(cs),max(cs),len(cells)))
                seen.update(cells)
    return res
